package com.intermarche.e2e.engine.fieldops;
import com.intermarche.backoffice.domain.shipping.*;
import com.intermarche.backoffice.domain.stock.StockMovement;
import com.intermarche.backoffice.domain.store.Employee;
import io.quarkus.test.junit.QuarkusTest;
import io.quarkus.narayana.jta.QuarkusTransaction;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static io.restassured.RestAssured.given;
@QuarkusTest @jakarta.enterprise.inject.Typed(FinalFulfillmentStepsTest.class)
class FinalFulfillmentStepsTest extends ParcelWorkflowTest {
 @Test void declaredParcelCountIsRealAndRetriesDoNotDuplicateIt(){prepared();var input=Map.of("storeId",f.store(),"orderId",customer,"count",3,"requestKey",key());var first=parcel(f.picker(),"/batch",input).then().statusCode(200).extract();parcel(f.picker(),"/batch",input).then().statusCode(200);assertEquals(3,first.jsonPath().getList("created").size());var summary=given().auth().oauth2(f.picker()).get("/parcels/declaration?storeId="+f.store()+"&orderId="+customer).then().statusCode(200).extract();assertEquals(4,summary.jsonPath().getInt("count"));assertEquals(0,summary.jsonPath().getInt("measuredCount"));parcel(f.picker(),"/batch",Map.of("storeId",f.store(),"orderId",customer,"count",0,"requestKey",key())).then().statusCode(400);}
 @Test void measuredTotalsDistinguishUnknownParcelsFromZero(){var p=save(prepared(),2);var summary=given().auth().oauth2(f.picker()).get("/parcels/declaration?storeId="+f.store()+"&orderId="+customer).then().statusCode(200).extract();assertEquals(1,summary.jsonPath().getInt("count"));assertEquals(1,summary.jsonPath().getInt("measuredCount"));assertEquals(1.25,summary.jsonPath().getDouble("weightKg"));assertEquals(0,summary.jsonPath().getInt("dimensionedCount"));}
 Map<String,Object> closed(){var p=save(prepared(),2);var close=input(p);close.put("contentsConfirmed",true);return parcel(f.picker(),"/close",close).then().statusCode(200).extract().jsonPath().getMap("$");}
 Map<String,Object> offer(Map<String,Object> p){long target=QuarkusTransaction.requiringNew().call(()->Employee.<Employee>find("store.id=?1 and role=?2",f.store(),Employee.EmployeeRole.MANAGER).firstResult().id);return new LinkedHashMap<>(Map.of("storeId",f.store(),"parcelId",p.get("id"),"recipientId",target,"step","SHIPPING","reason","Remettre au quai transporteur","requestKey",key()));}
 @Test void supportResponsibilityChangesOnlyAfterTheNamedRecipientAccepts(){var p=closed();long movements=QuarkusTransaction.requiringNew().call(()->StockMovement.count("account.store.id",f.store()));var offered=call(f.picker(),"POST","/support-handovers",offer(p)).then().statusCode(200).extract();String sender=offered.path("sender"),recipient=offered.path("recipient");assertEquals(sender,offered.path("responsible"));var accept=Map.of("storeId",f.store(),"id",offered.jsonPath().getLong("id"),"expectedRevision",offered.<String>path("revision"),"requestKey",key());call(f.picker(),"POST","/support-handovers/accept",accept).then().statusCode(403);String token=QuarkusTransaction.requiringNew().call(()->Employee.findByBadgeId(recipient).badgeId);token=login(token);var accepted=call(token,"POST","/support-handovers/accept",accept).then().statusCode(200).extract();call(token,"POST","/support-handovers/accept",accept).then().statusCode(200);assertEquals(recipient,accepted.path("responsible"));assertNotNull(accepted.path("acceptedAt"));QuarkusTransaction.requiringNew().run(()->assertEquals(movements,StockMovement.count("account.store.id",f.store())));}
 @Test void changedSupportCannotBeAcknowledgedAndCanBeCancelled(){var p=closed();var offered=call(f.picker(),"POST","/support-handovers",offer(p)).then().statusCode(200).extract();QuarkusTransaction.requiringNew().run(()->Parcel.<Parcel>findById(((Number)p.get("id")).longValue()).revisionNumber++);String receiver=login(offered.path("recipient"));var input=new LinkedHashMap<String,Object>(Map.of("storeId",f.store(),"id",offered.jsonPath().getLong("id"),"expectedRevision",offered.<String>path("revision"),"requestKey",key()));call(receiver,"POST","/support-handovers/accept",input).then().statusCode(409);input.put("requestKey",key());input.put("reason","Recontrôle nécessaire");call(f.picker(),"POST","/support-handovers/cancel",input).then().statusCode(200);}
 @Test void mistakenEmptyParcelCanBeRemovedWithoutChangingStock(){var p=prepared();var cancel=input(p);parcel(f.picker(),"/cancel",cancel).then().statusCode(200);parcel(f.picker(),"/cancel",cancel).then().statusCode(200);var summary=given().auth().oauth2(f.picker()).get("/parcels/declaration?storeId="+f.store()+"&orderId="+customer).then().statusCode(200).extract();assertEquals(0,summary.jsonPath().getInt("count"));}
 @Test void depositedBinCanBeAcknowledgedByTheNextStageWithoutMovingGoods(){prepared();var data=QuarkusTransaction.requiringNew().call(()->{var load=com.intermarche.backoffice.domain.executing.LoadedTote.<com.intermarche.backoffice.domain.executing.LoadedTote>find("tote.code",f.tote()).firstResult();var b=new com.intermarche.backoffice.domain.store.Buffer();b.bufferCode="STAGE-"+f.store();b.building=com.intermarche.backoffice.domain.store.Building.findById(f.building());b.active=true;b.ambientCapacity=10;b.persist();load.buffer=b;var e=com.intermarche.backoffice.client.PickingExecution.<com.intermarche.backoffice.client.PickingExecution>findById(f.execution());e.status=com.intermarche.backoffice.domain.handling.HandlingExecution.ExecutionStatus.DONE;e.handlingOrder.status=com.intermarche.backoffice.domain.wms.BaseHandlingOrder.HandlingOrderStatus.DONE;var target=Employee.<Employee>find("store.id=?1 and role=?2",f.store(),Employee.EmployeeRole.MANAGER).firstResult();return Map.of("load",load.id,"receiver",target.id,"badge",target.badgeId);});var offered=call(f.picker(),"POST","/support-handovers",Map.of("storeId",f.store(),"loadedToteId",data.get("load"),"recipientId",data.get("receiver"),"step","CONSOLIDATION","reason","Regrouper les commandes","requestKey",key())).then().statusCode(200).extract();call(login(data.get("badge").toString()),"POST","/support-handovers/accept",Map.of("storeId",f.store(),"id",offered.jsonPath().getLong("id"),"expectedRevision",offered.<String>path("revision"),"requestKey",key())).then().statusCode(200);}
 @Test void recipientsWhoCannotAcknowledgeAreNotProposed(){var p=closed();long cashier=QuarkusTransaction.requiringNew().call(()->{var e=new Employee();e.store=com.intermarche.backoffice.domain.store.Store.findById(f.store());e.badgeId="CASH-"+f.store();e.firstName="Caisse";e.lastName="Test";e.email=e.badgeId+"@example.test";e.password=org.mindrot.jbcrypt.BCrypt.hashpw("test",org.mindrot.jbcrypt.BCrypt.gensalt(4));e.active=true;e.role=Employee.EmployeeRole.CASHIER;e.persist();return e.id;});var people=call(f.picker(),"GET","/support-handovers/recipients?storeId="+f.store(),null).then().statusCode(200).extract().jsonPath().getList("badge");assertFalse(people.contains("CASH-"+f.store()));var invalid=offer(p);invalid.put("recipientId",cashier);call(f.picker(),"POST","/support-handovers",invalid).then().statusCode(400);}
}
